import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as s,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"ChatGPT Sites","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/codex/sites.md","filePath":"zh/products/ai-coding/codex/sites.md","lastUpdated":1787107158000}'),r={name:"zh/products/ai-coding/codex/sites.md"};function n(o,t,h,d,l,p){return s(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="chatgpt-sites" tabindex="-1">ChatGPT Sites <a class="header-anchor" href="#chatgpt-sites" aria-label="Permalink to &quot;ChatGPT Sites&quot;">​</a></h1><blockquote><p>这是一份<strong>教程</strong>——把一句提示词（或兼容的本地项目）变成<strong>托管</strong>网站或应用。Sites 是和 ChatGPT Work 并列的公开测试产品，不是脚注。每个部署 URL 都是生产。</p><p>官方落地页：<a href="https://learn.chatgpt.com/codex/sites" target="_blank" rel="noreferrer">learn.chatgpt.com/codex/sites</a>。文档：<a href="https://learn.chatgpt.com/docs/sites" target="_blank" rel="noreferrer">Sites</a>。管理：<a href="https://chatgpt.com/sites" target="_blank" rel="noreferrer">chatgpt.com/sites</a>。</p></blockquote><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需要</th><th>要求</th></tr></thead><tbody><tr><td>账号</td><td>套餐含 Sites。测试期限额全 Sites 共用——<a href="https://learn.chatgpt.com/docs/pricing" target="_blank" rel="noreferrer">定价</a></td></tr><tr><td>入口</td><td>ChatGPT <strong>网页</strong>或<strong>桌面应用</strong>。CLI 和 IDE <strong>没有</strong> Sites 管理界面</td></tr><tr><td>可选</td><td>要发布的本地项目；仍可用 Codex CLI / IDE 改源码</td></tr></tbody></table><p>可用性取决于套餐、地区和 workspace。撞上限会挡住新建、加存储或高流量公网站点；已有站点仍能改。</p><p><strong>学习目标</strong>：从提示词开一个 Site；部署前先 save version；选访问范围；分清 D1 / R2 和不用存储。</p><p><strong>非目标</strong>：把 Sites 当生产前端栈；Claude Design 那种品牌导入（这边没有这个产品）；CLI 沙箱（<a href="./codex-cli.html">CLI</a>）。</p><h2 id="sites-是什么-不是什么" tabindex="-1">Sites 是什么，不是什么 <a class="header-anchor" href="#sites-是什么-不是什么" aria-label="Permalink to &quot;Sites 是什么，不是什么&quot;">​</a></h2><p>Sites 让 ChatGPT <strong>创建、托管、改、分享</strong>网站、Web 应用和游戏。提示词里写 <code>website</code> 或 <code>@Sites</code> 就会进这条工作流。Site 是持久托管产物，创建它的 Work 会话结束了它还在。它<strong>不是</strong> ChatGPT Project。</p><p>它<strong>不是</strong>：</p><ul><li>Claude Design。没有「从代码库抽品牌规范再交接实现」的官方产品。</li><li>预发环境。部署 URL 对所选受众就是线上。</li><li>Codex CLI / IDE 面板。创建、保存、部署、管理走网页或桌面。CLI / IDE 只改、测本地源码。</li></ul><p>Work 仍是知识工作代理。本页是 Sites 产品。Work 里的短注在 <a href="./chatgpt-work.html#sites需要托管页面时">ChatGPT Work</a>。</p><h2 id="从哪打开" tabindex="-1">从哪打开 <a class="header-anchor" href="#从哪打开" aria-label="Permalink to &quot;从哪打开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>怎么走</th></tr></thead><tbody><tr><td>网页</td><td><strong>More → Sites</strong>，或 <a href="https://chatgpt.com/sites" target="_blank" rel="noreferrer">chatgpt.com/sites</a></td></tr><tr><td>桌面</td><td>ChatGPT 桌面应用里打开 <strong>Sites</strong></td></tr><tr><td>CLI / IDE</td><td>没有管理界面。本地项目在那边改；发布走网页或桌面</td></tr></tbody></table><h2 id="第一个-site-15-分钟" tabindex="-1">第一个 Site（15 分钟） <a class="header-anchor" href="#第一个-site-15-分钟" aria-label="Permalink to &quot;第一个 Site（15 分钟）&quot;">​</a></h2><h3 id="_1-写清受众和结果" tabindex="-1">1. 写清受众和结果 <a class="header-anchor" href="#_1-写清受众和结果" aria-label="Permalink to &quot;1. 写清受众和结果&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Build a project request dashboard for my operations team. Let team members</span></span>
<span class="line"><span>submit requests, see who owns each one, update the status, and filter the list.</span></span>
<span class="line"><span>Require people to sign in with their workspace account, and keep the request</span></span>
<span class="line"><span>data saved between visits.</span></span></code></pre></div><h3 id="_2-审行为-不只看截图" tabindex="-1">2. 审行为，不只看截图 <a class="header-anchor" href="#_2-审行为-不只看截图" aria-label="Permalink to &quot;2. 审行为，不只看截图&quot;">​</a></h3><p>查内容、数据处理、登录 / 未登录路径。</p><h3 id="_3-改" tabindex="-1">3. 改 <a class="header-anchor" href="#_3-改" aria-label="Permalink to &quot;3. 改&quot;">​</a></h3><p>直接说要改什么。证据是文件或截图就附上。</p><p>网页预览里 <strong>Edit → Describe website edits</strong>。需要额外上下文就用 <strong>Screenshot</strong> 或 <strong>Add files and more</strong>。</p><h3 id="_4-先-save-version-再-deploy" tabindex="-1">4. 先 save version，再 deploy <a class="header-anchor" href="#_4-先-save-version-再-deploy" aria-label="Permalink to &quot;4. 先 save version，再 deploy&quot;">​</a></h3><p>桌面 / 本地项目分两步：</p><ol><li><strong>Save a version</strong> — 可审候选。本地源码项目会绑到这次构建用的 Git commit。</li><li><strong>Deploy a version</strong> — 发布该候选，给出生产 URL。</li></ol><p>要先审，就让 ChatGPT <strong>save a version without deploying</strong>。</p><h3 id="_5-用最窄的受众分享" tabindex="-1">5. 用最窄的受众分享 <a class="header-anchor" href="#_5-用最窄的受众分享" aria-label="Permalink to &quot;5. 用最窄的受众分享&quot;">​</a></h3><p>新 Site 默认只有所有者和 workspace 管理员能看，直到你改访问。</p><h2 id="项目、版本、-openai-hosting-json" tabindex="-1">项目、版本、<code>.openai/hosting.json</code> <a class="header-anchor" href="#项目、版本、-openai-hosting-json" aria-label="Permalink to &quot;项目、版本、\`.openai/hosting.json\`&quot;">​</a></h2><p>桌面 / 本地项目里，Sites 把关联和可选存储绑定名写在 <code>.openai/hosting.json</code>。新 starter 可能还没有 <code>project_id</code>，托管建好后才会补。</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;project_id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;project-id&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;d1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DB&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;r2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>不要</strong>把密钥写进这个文件。托管环境变量在 Site 的 <strong>Settings</strong>。本地 <code>.env</code> / <code>.env.example</code> 只对齐键名。</p><p>发布已有兼容应用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Deploy this project with Sites. Check whether it is compatible, make any</span></span>
<span class="line"><span>required changes, and give me the deployment URL.</span></span></code></pre></div><h2 id="选站点形态" tabindex="-1">选站点形态 <a class="header-anchor" href="#选站点形态" aria-label="Permalink to &quot;选站点形态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>向 Sites 要</th></tr></thead><tbody><tr><td>落地页 / 内容站</td><td>除非必要，不要持久应用状态</td></tr><tr><td>记录、分数、进度</td><td><strong>D1</strong>（关系库）</td></tr><tr><td>上传（图、文档、媒体）</td><td><strong>R2</strong>（对象存储）</td></tr><tr><td>上传 + 可搜元数据</td><td>D1 + R2</td></tr><tr><td>内部、当前 workspace 用户</td><td>Workspace 身份</td></tr><tr><td>公网登录</td><td>打开认证的 Site</td></tr></tbody></table><p>主题开关不要持久存储。用户刷新后还要在的数据才要。</p><h2 id="访问、sign-in-with-chatgpt、域名" tabindex="-1">访问、Sign in with ChatGPT、域名 <a class="header-anchor" href="#访问、sign-in-with-chatgpt、域名" aria-label="Permalink to &quot;访问、Sign in with ChatGPT、域名&quot;">​</a></h2><p>分享让人<strong>访问</strong>，不让人编辑。</p><p>常见选项（看账号和 workspace）：所有者 + 管理员；指定用户或组；workspace 内所有人；互联网任何人（仅当公网发布打开）。企业默认<strong>关</strong>公网发布。</p><p>Workspace 限制的 Site 已经用 ChatGPT 身份。公网站点可以继续开放，并加上可选 <strong>Sign in with ChatGPT</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Add Sign in with ChatGPT to this public Site. Keep the Site available to</span></span>
<span class="line"><span>signed-out visitors. After they sign in, greet them with their full name</span></span>
<span class="line"><span>when available, or their email address otherwise. Keep authorization</span></span>
<span class="line"><span>decisions in server-side code.</span></span></code></pre></div><p>平台路径：<code>/signin-with-chatgpt</code>、<code>/signout-with-chatgpt</code>。身份在 <code>oai-authenticated-user-email</code> 和可选的 <code>oai-authenticated-user-full-name</code>。授权放服务端。</p><p>自定义域名（可用时）：你已经拥有 apex 或子域；Sites 不代注册。企业上线时不可用。加上 Sites 给出的 DNS，等一会儿，刷新状态。</p><h2 id="分析和下线" tabindex="-1">分析和下线 <a class="header-anchor" href="#分析和下线" aria-label="Permalink to &quot;分析和下线&quot;">​</a></h2><p>流量自动记，不用嵌分析 SDK：独立访客和 PV 随时间变化。打开 Site → <strong>More actions → Analytics</strong>。企业 workspace 拥有的 Site 暂无分析。</p><p>不下线删除：收紧分享，确认旧受众打不开。</p><p>永久删除：<strong>Delete site</strong> → 输入 slug → <strong>Permanently delete</strong>。不能恢复。</p><h2 id="限制和不支持的用途" tabindex="-1">限制和不支持的用途 <a class="header-anchor" href="#限制和不支持的用途" aria-label="Permalink to &quot;限制和不支持的用途&quot;">​</a></h2><p>Sites 跑在受支持的运行时。部分框架、私网、数据库、后台服务、托管形态不支持。</p><p>上线时不支持数据驻留或推理驻留——包括站点代码、D1 / R2、产物和日志。</p><p><strong>NEVER</strong> 用 Sites 处理 PHI、卡数据、13 岁以下（或当地数字同意年龄）儿童、金融交易、恶意软件、钓鱼、假冒，或其它违反政策的用途。现行政策：<a href="https://help.openai.com/en/articles/20001339" target="_blank" rel="noreferrer">Creating and managing ChatGPT Sites</a>。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><table tabindex="0"><thead><tr><th>陷阱</th><th>结果</th><th>改做</th></tr></thead><tbody><tr><td>把部署当「预览」</td><td>URL 就是生产</td><td>先 save version，审完再 deploy</td></tr><tr><td>在 CLI 里找 Sites</td><td>没有管理界面</td><td>网页或桌面</td></tr><tr><td>密钥写进提示词或 <code>hosting.json</code></td><td>泄露</td><td>托管密钥走 Site <strong>Settings</strong></td></tr><tr><td>把 Sites 当生产应用平台</td><td>运行时 / 驻留 / 政策限制</td><td>给内部工具和测试；真生产放别处</td></tr><tr><td>把 Site 和 ChatGPT Project 搞混</td><td>列表和生命周期都不对</td><td>去 <a href="https://chatgpt.com/sites" target="_blank" rel="noreferrer">chatgpt.com/sites</a></td></tr></tbody></table><h2 id="实际用例" tabindex="-1">实际用例 <a class="header-anchor" href="#实际用例" aria-label="Permalink to &quot;实际用例&quot;">​</a></h2><p>前端组要一块内部需求板：写清受众，要求 workspace 登录，要 D1 让行能留下来，先 save version，让同事打开 URL，再 deploy。长寿命组件库在仓库里用 <a href="./codex-cli.html">Codex</a> 写；Sites 只托管壳，不当设计系统。</p><p>展示（提示词和线上应用）：<a href="https://developers.openai.com/showcase" target="_blank" rel="noreferrer">developers.openai.com/showcase</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ol><li>Work vs Codex vs Sites → <a href="./">学习地图</a></li><li>Work 代理（PPT、插件、定时） → <a href="./chatgpt-work.html">ChatGPT Work</a></li><li>本地源码 + review pane → <a href="https://learn.chatgpt.com/docs/code-review?surface=app" target="_blank" rel="noreferrer">Code review</a></li></ol><h2 id="官方来源" tabindex="-1">官方来源 <a class="header-anchor" href="#官方来源" aria-label="Permalink to &quot;官方来源&quot;">​</a></h2><ul><li><a href="https://learn.chatgpt.com/codex/sites" target="_blank" rel="noreferrer">Sites（落地页）</a></li><li><a href="https://learn.chatgpt.com/docs/sites" target="_blank" rel="noreferrer">Sites（文档）</a></li><li><a href="https://chatgpt.com/sites" target="_blank" rel="noreferrer">chatgpt.com/sites</a></li><li><a href="https://help.openai.com/en/articles/20001339" target="_blank" rel="noreferrer">Creating and managing ChatGPT Sites</a></li><li><a href="https://help.openai.com/en/articles/20001340" target="_blank" rel="noreferrer">隐私 / 数据保护</a></li></ul>`,61)])])}const m=e(r,[["render",n]]);export{b as __pageData,m as default};
